codeblock1Html: "\n<span class=\"hljs-comment\">//#region constants</span>\n<span class=\"hljs-built_in\">console</span>.log(<span class=\"hljs-string\">&#x27;🚀 [ TAON IS STARTING ]&#x27;</span>);\n<span class=\"hljs-keyword\">const</span> DEFAULT_PASSWORD = DEFAULT_SESSION_PASSWORD;\n\n<span class=\"hljs-keyword\">const</span> DEFAULT_EMAIL = DEFAULT_SESSION_EMAIL;\n\n<span class=\"hljs-keyword\">const</span> DEFAULT_PASSWORD2 = DEFAULT_SESSION_PASSWORD;\n\n<span class=\"hljs-keyword\">const</span> DEFAULT_EMAIL2 = <span class=\"hljs-number\">2</span> + DEFAULT_SESSION_EMAIL;\n\n<span class=\"hljs-keyword\">const</span> DEFAULT_PASSWORD3 = DEFAULT_SESSION_PASSWORD;\n\n<span class=\"hljs-keyword\">const</span> DEFAULT_EMAIL3 = <span class=\"hljs-string\">&#x27;dariusz@taon.dev&#x27;</span>;\n<span class=\"hljs-comment\">//#endregion</span>\n<span class=\"hljs-keyword\">const</span> t = Translation.for(Taon.__FILE_RELATIVE_PATH, Taon.LANG_IMPORT_MAP, {\n  <span class=\"hljs-comment\">// debug: true</span>\n});\n",
