codeblock3Html: "<span class=\"hljs-comment\">//#region @browser</span>\n<span class=\"hljs-keyword\">export</span> <span class=\"hljs-keyword\">const</span> CmsServerRoutes: ServerRoute[] = [\n  {\n    <span class=\"hljs-attr\">path</span>: <span class=\"hljs-string\">&#x27;**&#x27;</span>,\n    <span class=\"hljs-attr\">renderMode</span>: RenderMode.Prerender,\n  },\n];\n<span class=\"hljs-keyword\">export</span> <span class=\"hljs-keyword\">const</span> CmsClientRoutes: Routes = [\n  {\n    <span class=\"hljs-attr\">path</span>: <span class=\"hljs-string\">&#x27;&#x27;</span>,\n    <span class=\"hljs-attr\">pathMatch</span>: <span class=\"hljs-string\">&#x27;full&#x27;</span>,\n    <span class=\"hljs-attr\">redirectTo</span>: <span class=\"hljs-string\">&#x27;app&#x27;</span>,\n  },\n  {\n    <span class=\"hljs-comment\">// SessionExampleRoutes</span>\n    <span class=\"hljs-attr\">path</span>: <span class=\"hljs-string\">&#x27;app&#x27;</span>,\n    <span class=\"hljs-attr\">loadChildren</span>: <span class=\"hljs-function\">() =&gt;</span>\n      <span class=\"hljs-keyword\">import</span>(<span class=\"hljs-string\">&#x27;./app/cms-example/cms-example.routes&#x27;</span>).then(\n        <span class=\"hljs-function\"><span class=\"hljs-params\">m</span> =&gt;</span> m.CmsExampleRoutes,\n      ),\n  },\n  {\n    <span class=\"hljs-attr\">path</span>: <span class=\"hljs-string\">&#x27;backoffice&#x27;</span>,\n    <span class=\"hljs-attr\">outlet</span>: TaonBaselineBackofficeOutletName,\n    <span class=\"hljs-attr\">providers</span>: [\n      {\n        <span class=\"hljs-attr\">provide</span>: TAON_CONTEXT,\n        <span class=\"hljs-attr\">useFactory</span>: <span class=\"hljs-function\">() =&gt;</span> CmsContext,\n      },\n    ],\n    <span class=\"hljs-attr\">loadChildren</span>: <span class=\"hljs-function\">() =&gt;</span>\n      <span class=\"hljs-keyword\">import</span>(<span class=\"hljs-string\">&#x27;./app/baseline-backoffice/taon-baseline-backoffice.routes&#x27;</span>).then(\n        <span class=\"hljs-function\"><span class=\"hljs-params\">m</span> =&gt;</span> m.TaonBaselineBackofficeRoutes,\n      ),\n  },\n  <span class=\"hljs-comment\">// PUT ALL ROUTES HERE</span>\n  <span class=\"hljs-comment\">// @placeholder-for-routes</span>\n\n  <span class=\"hljs-comment\">// uncomment this to have NOT FOUND route</span>\n  <span class=\"hljs-comment\">// {</span>\n  <span class=\"hljs-comment\">//   path: &#x27;**&#x27;,</span>\n  <span class=\"hljs-comment\">//   component: TaonNotFoundComponent,</span>\n  <span class=\"hljs-comment\">// },</span>\n];\n<span class=\"hljs-comment\">//#endregion</span>\n",
