codeblock4: "//#region @browser\nexport const CmsAppConfig: ApplicationConfig = {\n  providers: [\n    provideZonelessChangeDetection(),\n    {\n      provide: TAON_CONTEXT,\n      useFactory: () => CmsContext,\n    },\n    providePrimeNG({\n      theme: {\n        preset: Aura,\n      },\n    }),\n    {\n      provide: APP_INITIALIZER,\n      multi: true,\n      useFactory: () => CmsStartFunction,\n    },\n    provideBrowserGlobalErrorListeners(),\n    // remove withHashLocation() to use SSR\n    provideRouter(\n      CmsClientRoutes,\n      withHashLocation(),\n      withComponentInputBinding(),\n    ),\n    provideClientHydration(withEventReplay()),\n    provideServiceWorker('ngsw-worker.js', {\n      enabled:\n        !isDevMode() && !ENV_ANGULAR_NODE_APP_BUILD_PWA_DISABLE_SERVICE_WORKER,\n      registrationStrategy: 'registerWhenStable:30000',\n    }),\n  ],\n};\n\nexport const CmsServerConfig: ApplicationConfig = {\n  providers: [provideServerRendering(withRoutes(CmsServerRoutes))],\n};\n\nexport const CmsConfig = mergeApplicationConfig(CmsAppConfig, CmsServerConfig);\n//#endregion\n",
// @taonSkipNextLineCut
codeblock4Html: "<span class=\"hljs-comment\">//#region @browser</span>\n<span class=\"hljs-keyword\">export</span> <span class=\"hljs-keyword\">const</span> CmsAppConfig: ApplicationConfig = {\n  <span class=\"hljs-attr\">providers</span>: [\n    provideZonelessChangeDetection(),\n    {\n      <span class=\"hljs-attr\">provide</span>: TAON_CONTEXT,\n      <span class=\"hljs-attr\">useFactory</span>: <span class=\"hljs-function\">() =&gt;</span> CmsContext,\n    },\n    providePrimeNG({\n      <span class=\"hljs-attr\">theme</span>: {\n        <span class=\"hljs-attr\">preset</span>: Aura,\n      },\n    }),\n    {\n      <span class=\"hljs-attr\">provide</span>: APP_INITIALIZER,\n      <span class=\"hljs-attr\">multi</span>: <span class=\"hljs-literal\">true</span>,\n      <span class=\"hljs-attr\">useFactory</span>: <span class=\"hljs-function\">() =&gt;</span> CmsStartFunction,\n    },\n    provideBrowserGlobalErrorListeners(),\n    <span class=\"hljs-comment\">// remove withHashLocation() to use SSR</span>\n    provideRouter(\n      CmsClientRoutes,\n      withHashLocation(),\n      withComponentInputBinding(),\n    ),\n    provideClientHydration(withEventReplay()),\n    provideServiceWorker(<span class=\"hljs-string\">&#x27;ngsw-worker.js&#x27;</span>, {\n      <span class=\"hljs-attr\">enabled</span>:\n        !isDevMode() &amp;&amp; !ENV_ANGULAR_NODE_APP_BUILD_PWA_DISABLE_SERVICE_WORKER,\n      <span class=\"hljs-attr\">registrationStrategy</span>: <span class=\"hljs-string\">&#x27;registerWhenStable:30000&#x27;</span>,\n    }),\n  ],\n};\n\n<span class=\"hljs-keyword\">export</span> <span class=\"hljs-keyword\">const</span> CmsServerConfig: ApplicationConfig = {\n  <span class=\"hljs-attr\">providers</span>: [provideServerRendering(withRoutes(CmsServerRoutes))],\n};\n\n<span class=\"hljs-keyword\">export</span> <span class=\"hljs-keyword\">const</span> CmsConfig = mergeApplicationConfig(CmsAppConfig, CmsServerConfig);\n<span class=\"hljs-comment\">//#endregion</span>\n",
