codeblock5: "var CmsContext = Taon.createContext(() => ({\n  ...HOST_CONFIG['CmsContext'],\n  contexts: {\n    TaonCmsAbstractContext,\n    TaonSudoAbstractContext,\n    TaonBaseContext,\n  },\n  migrations: {\n    ...MIGRATIONS_CLASSES_FOR_CmsContext,\n  },\n  providers: {\n    [ClassHelpers.getName(TaonSessionProvider)]: TaonSessionProviderDecorator,\n    [ClassHelpers.getName(TaonCmsContentProvider)]:\n      TaonCmsContentProviderDecorator,\n  },\n  entities: {\n    [ClassHelpers.getName(TaonAuthContextEntity)]:\n      TaonAuthContextEntityDecorator,\n  },\n  repositories: {\n    [ClassHelpers.getName(TaonAuthContextRepository)]:\n      TaonAuthContextRepositoryDecorator,\n  },\n  logs: {\n    // db\n    migrations: true,\n  },\n  database: true,\n  disabledRealtime: true,\n}));\n",
// @taonSkipNextLineCut
codeblock5Html: "<span class=\"hljs-keyword\">var</span> CmsContext = Taon.createContext(<span class=\"hljs-function\">() =&gt;</span> ({\n  ...HOST_CONFIG[<span class=\"hljs-string\">&#x27;CmsContext&#x27;</span>],\n  <span class=\"hljs-attr\">contexts</span>: {\n    TaonCmsAbstractContext,\n    TaonSudoAbstractContext,\n    TaonBaseContext,\n  },\n  <span class=\"hljs-attr\">migrations</span>: {\n    ...MIGRATIONS_CLASSES_FOR_CmsContext,\n  },\n  <span class=\"hljs-attr\">providers</span>: {\n    [ClassHelpers.getName(TaonSessionProvider)]: TaonSessionProviderDecorator,\n    [ClassHelpers.getName(TaonCmsContentProvider)]:\n      TaonCmsContentProviderDecorator,\n  },\n  <span class=\"hljs-attr\">entities</span>: {\n    [ClassHelpers.getName(TaonAuthContextEntity)]:\n      TaonAuthContextEntityDecorator,\n  },\n  <span class=\"hljs-attr\">repositories</span>: {\n    [ClassHelpers.getName(TaonAuthContextRepository)]:\n      TaonAuthContextRepositoryDecorator,\n  },\n  <span class=\"hljs-attr\">logs</span>: {\n    <span class=\"hljs-comment\">// db</span>\n    <span class=\"hljs-attr\">migrations</span>: <span class=\"hljs-literal\">true</span>,\n  },\n  <span class=\"hljs-attr\">database</span>: <span class=\"hljs-literal\">true</span>,\n  <span class=\"hljs-attr\">disabledRealtime</span>: <span class=\"hljs-literal\">true</span>,\n}));\n",
